ype\":\"message\",\"message\":\"Thanks for reaching out! Tanya will get back to you shortly.\",\"message_scroll\":\"1\"}},\"ajax_submit\":\"1\",\"store_spam_entries\":\"0\"},\"id\":\"40\"}','Contact Form','','inherit','closed','closed','','40-revision-v1','','','2026-07-08 20:42:26','2026-07-08 20:42:26','',40,'http://tanya-barrans.local/?p=43',0,'revision','',0),(44,1,'2026-07-08 20:44:33','2026-07-08 20:44:33','{\"fields\":{\"1\":{\"id\":\"1\",\"type\":\"name\",\"format\":\"first-last\",\"label\":\"Name\",\"required\":\"1\",\"size\":\"medium\"},\"2\":{\"id\":\"2\",\"type\":\"email\",\"label\":\"Email\",\"required\":\"1\",\"size\":\"medium\",\"allowlist\":\"\",\"denylist\":\"\",\"default_value\":\"\"},\"3\":{\"id\":\"3\",\"type\":\"text\",\"label\":\"Phone\",\"placeholder\":\"(555) 555-0100\",\"required\":\"\",\"size\":\"medium\"},\"4\":{\"id\":\"4\",\"type\":\"textarea\",\"label\":\"How can Tanya help?\",\"size\":\"medium\",\"placeholder\":\"Tell me a bit about what you\'re looking for...\",\"css\":\"\"}},\"field_id\":5,\"settings\":{\"form_title\":\"Contact Form\",\"form_desc\":\"\",\"submit_text\":\"Send Message\",\"submit_text_processing\":\"Sending...\",\"antispam_v3\":\"1\",\"notification_enable\":\"1\",\"notifications\":{\"1\":{\"notification_name\":\"Notification 1\",\"email\":\"{admin_email}\",\"replyto\":\"{field_id=\\\"2\\\"}\",\"subject\":\"New contact form submission from {field_id=\\\"1\\\"}\",\"message\":\"{all_fields}\"}},\"confirmations\":{\"1\":{\"confirmation_name\":\"Confirmation 1\",\"type\":\"message\",\"message\":\"Thanks for reaching out! Tanya will get back to you shortly.\",\"message_scroll\":\"1\"}},\"ajax_submit\":\"1\",\"store_spam_entries\":\"0\"},\"id\":\"40\"}','Contact Form','','inherit','closed','closed','','40-revision-v1','','','2026-07-08 20:44:33','2026-07-08 20:44:33','',40,'http://tanya-barrans.local/?p=44',0,'revision','',0),(45,0,'2026-07-08 21:05:24','2026-07-08 21:05:24','<!-- wp:pattern {\"slug\":\"tanya-barrans/about-intro\"} /-->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"720px\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--40)\">\n\n	<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-eyebrow\"} -->\n	<p class=\"has-text-align-center tb-eyebrow\">Your Local Real Estate Expert</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"xx-large\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|40\"}}}} -->\n	<h2 class=\"wp-block-heading has-text-align-center has-xx-large-font-size\" style=\"margin-bottom:var(--wp--preset--spacing--40)\">I\'m here to make this feel like home.</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n	<p class=\"has-muted-color has-text-color\">Buying or selling a home is one of the biggest decisions you\'ll make, and it shouldn\'t feel like you\'re figuring it out alone. Whether you\'re searching for your first home, selling the place where you\'ve made years of memories, or simply wondering if now is the right time to make a move, my job is to give you honest advice, a smart strategy, and the confidence to move forward.</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n	<p class=\"has-muted-color has-text-color\">I\'ve built my business around knowing the communities I serve — not just the statistics, but the neighborhoods, schools, commute patterns, hidden gems, and market trends that help my clients make better decisions. From Renton and Kent to Maple Valley, Covington, Newcastle, and the surrounding communities, I know what makes each area unique because this is home, too.</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n	<p class=\"has-muted-color has-text-color\">Every client receives a customized marketing and pricing strategy designed around their goals, not a one-size-fits-all plan. Professional photography, Zillow Showcase, video, digital marketing, and strategic negotiation all work together to help you achieve the best possible outcome.</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n	<p class=\"has-muted-color has-text-color\">But here\'s what I hope you\'ll remember most. By the time we get to closing, there\'s a good chance we\'ll be talking about more than real estate. I\'ll probably have you planning your first vegetable garden, convincing you to try homemade sourdough, or texting you recommendations for the best local spots after you\'ve moved in. Because while I love helping people buy and sell homes, my favorite part has always been the relationships that come with it.</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"align\":\"center\",\"fontFamily\":\"serif\",\"style\":{\"typography\":{\"fontStyle\":\"italic\",\"fontSize\":\"1.375rem\",\"lineHeight\":\"1.5\"},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n	<p class=\"has-text-align-center has-serif-font-family\" style=\"margin-top:var(--wp--preset--spacing--40);font-size:1.375rem;font-style:italic;line-height:1.5\">My goal isn\'t just to help you find the right house. It\'s to help you feel at home long before you unpack the first box.</p>\n	<!-- /wp:paragraph -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull has-alabaster-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--40)\">\n\n	<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-eyebrow\"} -->\n	<p class=\"has-text-align-center tb-eyebrow\">A Little More Personality</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"xx-large\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|40\"}}}} -->\n	<h2 class=\"wp-block-heading has-text-align-center has-xx-large-font-size\" style=\"margin-bottom:var(--wp--preset--spacing--40)\">Real estate, minus the stuffiness</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|30\"}}}} -->\n	<div class=\"wp-block-columns alignwide\">\n\n		<!-- wp:column {\"className\":\"tb-reveal\"} -->\n		<div class=\"wp-block-column tb-reveal\">\n			<!-- wp:image {\"id\":19,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"tb-card\",\"style\":{\"border\":{\"radius\":\"4px\"}}} -->\n			<figure class=\"wp-block-image size-full tb-card has-custom-border\"><img src=\"http://tanya-barrans.local/wp-content/uploads/2026/07/gallery-1.jpg\" alt=\"Tanya Barrans smiling, seated\" class=\"wp-image-19\" style=\"border-radius:4px;aspect-ratio:3/4;object-fit:cover;width:100%\"/></figure>\n			<!-- /wp:image -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-reveal\"} -->\n		<div class=\"wp-block-column tb-reveal\">\n			<!-- wp:image {\"id\":25,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"tb-card\",\"style\":{\"border\":{\"radius\":\"4px\"}}} -->\n			<figure class=\"wp-block-image size-full tb-card has-custom-border\"><img src=\"http://tanya-barrans.local/wp-content/uploads/2026/07/gallery-2-new.jpg\" alt=\"Tanya Barrans smiling, hands on hips\" class=\"wp-image-25\" style=\"border-radius:4px;aspect-ratio:3/4;object-fit:cover;width:100%\"/></figure>\n			<!-- /wp:image -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-reveal\"} -->\n		<div class=\"wp-block-column tb-reveal\">\n			<!-- wp:image {\"id\":21,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"tb-card\",\"style\":{\"border\":{\"radius\":\"4px\"}}} -->\n			<figure class=\"wp-block-image size-full tb-card has-custom-border\"><img src=\"http://tanya-barrans.local/wp-content/uploads/2026/07/gallery-3.jpg\" alt=\"Tanya Barrans laughing, full length\" class=\"wp-image-21\" style=\"border-radius:4px;aspect-ratio:3/4;object-fit:cover;width:100%;object-position:top\"/></figure>\n			<!-- /wp:image -->\n		</div>\n		<!-- /wp:column -->\n\n	</div>\n	<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n','About','','inherit','closed','closed','','6-revision-v1','','','2026-07-08 21:05:24','2026-07-08 21:05:24','',6,'http://tanya-barrans.local/?p=45',0,'revision','',0),(46,0,'2026-07-08 21:07:26','2026-07-08 21:07:26','<!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\">\n\n	<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"120px\"} -->\n	<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:120px\">\n		<!-- wp:image {\"id\":18,\"width\":\"120px\",\"height\":\"120px\",\"sizeSlug\":\"medium\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"999px\"}}} -->\n		<figure class=\"wp-block-image size-medium is-resized has-custom-border\"><img src=\"http://tanya-barrans.local/wp-content/uploads/2026/07/contact-circle-300x300.jpg\" alt=\"Tanya Barrans, Puget Sound real estate broker\" class=\"wp-image-18\" style=\"border-radius:999px;width:120px;height:120px;object-fit:cover\"/></figure>\n		<!-- /wp:image -->\n	</div>\n	<!-- /wp:column -->\n\n	<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n	<div class=\"wp-block-column is-vertically-aligned-center\">\n		<!-- wp:heading -->\n		<h2 class=\"wp-block-heading\">Let\'s talk about your move</h2>\n		<!-- /wp:heading -->\n		<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n		<p class=\"has-muted-color has-text-color\">Whether you have a specific question or just want to explore what\'s possible, reach out anytime.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:column -->\n\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p><strong>Email:</strong> tanya@example.com<br><strong>Phone:</strong> (555) 555-0100</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--30)\">\n	<!-- wp:button {\"className\":\"tb-button-outline\",\"textColor\":\"ink\"} -->\n	<div class=\"wp-block-button tb-button-outline\"><a class=\"wp-block-button__link has-ink-color has-text-color wp-element-button\" href=\"https://calendar.app.google/zndHShd1Rm6W6Qb38\" target=\"_blank\" rel=\"noopener noreferrer\">Schedule a Call →</a></div>\n	<!-- /wp:button -->\n</div>\n<!-- /wp:buttons -->\n\n<!-- wp:group {\"className\":\"tb-content-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"var:preset|spacing|50\"}},\"border\":{\"radius\":\"8px\"}},\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group tb-content-card has-alabaster-background-color has-background\" style=\"border-radius:8px;margin-top:var(--wp--preset--spacing--50);padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\">\n	<!-- wp:wpforms/form-selector {\"formId\":\"40\",\"displayTitle\":false,\"displayDesc\":false} /-->\n</div>\n<!-- /wp:group -->\n','Contact','','inherit','closed','closed','','11-revision-v1','','','2026-07-08 21:07:26','2026-07-08 21:07:26','',11,'http://tanya-barrans.local/?p=46',0,'revision','',0),(47,0,'2026-07-08 21:58:51','2026-07-08 21:58:51','<!-- wp:paragraph {\"textColor\":\"muted\",\"fontSize\":\"large\"} -->\n<p class=\"has-muted-color has-text-color has-large-font-size\">Buying a home is exciting and overwhelming, sometimes in the same afternoon. Whether it\'s your first place or your fifth, I\'ll help you navigate it with a clear plan, honest advice, and zero pressure.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"tb-topo-bg\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull tb-topo-bg has-alabaster-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--40)\">\n\n	<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-eyebrow\"} -->\n	<p class=\"has-text-align-center tb-eyebrow\">The Process</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"xx-large\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|50\"}}}} -->\n	<h2 class=\"wp-block-heading has-text-align-center has-xx-large-font-size\" style=\"margin-bottom:var(--wp--preset--spacing--50)\">From first search to closing day</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|40\"}}}} -->\n	<div class=\"wp-block-columns alignwide\">\n\n		<!-- wp:column {\"className\":\"tb-card tb-reveal\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"base\"} -->\n		<div class=\"wp-block-column tb-card tb-reveal has-base-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\">\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">Step 1</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":3} -->\n			<h3 class=\"wp-block-heading\">Let\'s Talk</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"has-muted-color has-text-color has-small-font-size\">A no-pressure conversation about your budget, timeline, and what you\'re actually looking for — not just a checklist of features.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-card tb-reveal\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"base\"} -->\n		<div class=\"wp-block-column tb-card tb-reveal has-base-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\">\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">Step 2</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":3} -->\n			<h3 class=\"wp-block-heading\">The Search</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"has-muted-color has-text-color has-small-font-size\">Private showings, honest neighborhood insight, and early alerts on homes that fit — before they\'re all over your feed.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-card tb-reveal\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"base\"} -->\n		<div class=\"wp-block-column tb-card tb-reveal has-base-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\">\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">Step 3</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":3} -->\n			<h3 class=\"wp-block-heading\">The Offer</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"has-muted-color has-text-color has-small-font-size\">A pricing strategy grounded in real local data, and someone in your corner through every round of negotiation.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-card tb-reveal\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"base\"} -->\n		<div class=\"wp-block-column tb-card tb-reveal has-base-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\">\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">Step 4</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":3} -->\n			<h3 class=\"wp-block-heading\">Closing Day</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"has-muted-color has-text-color has-small-font-size\">Inspections, appraisals, title, and escrow — all handled and explained in plain English, right up to the keys in your hand.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n	</div>\n	<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n<p class=\"tb-eyebrow\">Where I Work</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2,\"fontSize\":\"x-large\"} -->\n<h2 class=\"wp-block-heading has-x-large-font-size\">Renton, Kent, and the surrounding Puget Sound</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n<p class=\"has-muted-color has-text-color\">I focus on Renton, Kent, Covington, Maple Valley, Newcastle, and the communities around them — not because it\'s convenient, but because I actually know these neighborhoods: the schools, the commutes, the hidden gems, and what a fair price really looks like block by block. If you\'re searching somewhere nearby that isn\'t listed here, reach out anyway — there\'s a good chance I can still help.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--40)\">\n	<!-- wp:button -->\n	<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/listings/\">Find Your Next Home</a></div>\n	<!-- /wp:button -->\n\n	<!-- wp:button {\"className\":\"tb-button-outline\",\"textColor\":\"ink\"} -->\n	<div class=\"wp-block-button tb-button-outline\"><a class=\"wp-block-button__link has-ink-color has-text-color wp-element-button\" href=\"/contact/\">Get In Touch</a></div>\n	<!-- /wp:button -->\n</div>\n<!-- /wp:buttons -->\n','Buy','','inherit','closed','closed','','7-revision-v1','','','2026-07-08 21:58:51','2026-07-08 21:58:51','',7,'http://tanya-barrans.local/?p=47',0,'revision','',0),(48,0,'2026-07-08 21:58:55','2026-07-08 21:58:55','<!-- wp:paragraph {\"textColor\":\"muted\",\"fontSize\":\"large\"} -->\n<p class=\"has-muted-color has-text-color has-large-font-size\">Selling the place where you\'ve made memories is personal — and getting it sold for what it\'s worth takes more than a sign in the yard. Here\'s how I get your home ready, seen, and sold.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"tb-topo-bg\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull tb-topo-bg has-alabaster-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--40)\">\n\n	<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-eyebrow\"} -->\n	<p class=\"has-text-align-center tb-eyebrow\">The Process</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"xx-large\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|50\"}}}} -->\n	<h2 class=\"wp-block-heading has-text-align-center has-xx-large-font-size\" style=\"margin-bottom:var(--wp--preset--spacing--50)\">From pricing strategy to sold</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|40\"}}}} -->\n	<div class=\"wp-block-columns alignwide\">\n\n		<!-- wp:column {\"className\":\"tb-card tb-reveal\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"base\"} -->\n		<div class=\"wp-block-column tb-card tb-reveal has-base-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\">\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">Step 1</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":3} -->\n			<h3 class=\"wp-block-heading\">Pricing Strategy</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"has-muted-color has-text-color has-small-font-size\">A customized pricing plan based on real local data — not a national average that has no idea what street you live on.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-card tb-reveal\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"base\"} -->\n		<div class=\"wp-block-column tb-card tb-reveal has-base-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\">\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">Step 2</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":3} -->\n			<h3 class=\"wp-block-heading\">Staging &amp; Photos</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"has-muted-color has-text-color has-small-font-size\">Staging guidance, professional photography, and video that shows your home at its best from the very first click.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-card tb-reveal\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"base\"} -->\n		<div class=\"wp-block-column tb-card tb-reveal has-base-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\">\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">Step 3</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":3} -->\n			<h3 class=\"wp-block-heading\">Marketing</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"has-muted-color has-text-color has-small-font-size\">Zillow Showcase, digital marketing, and strategic exposure that puts your listing in front of the right buyers, fast.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-card tb-reveal\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"base\"} -->\n		<div class=\"wp-block-column tb-card tb-reveal has-base-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\">\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">Step 4</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":3} -->\n			<h3 class=\"wp-block-heading\">Negotiation &amp; Close</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"has-muted-color has-text-color has-small-font-size\">Firm, fair negotiation on every offer, then a smooth path through inspections, appraisal, and closing.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n	</div>\n	<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n<p class=\"tb-eyebrow\">What\'s Included</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2,\"fontSize\":\"x-large\"} -->\n<h2 class=\"wp-block-heading has-x-large-font-size\">Full-service, start to finish</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"style\":{\"spacing\":{\"padding\":{\"left\":\"0\"}}},\"className\":\"is-style-none\"} -->\n<ul class=\"wp-block-list is-style-none\" style=\"padding-left:0\">\n	<!-- wp:list-item --><li>Comparative market analysis &amp; pricing strategy</li><!-- /wp:list-item -->\n	<!-- wp:list-item --><li>Staging consultation</li><!-- /wp:list-item -->\n	<!-- wp:list-item --><li>Professional photography &amp; video</li><!-- /wp:list-item -->\n	<!-- wp:list-item --><li>Zillow Showcase &amp; digital marketing</li><!-- /wp:list-item -->\n	<!-- wp:list-item --><li>Strategic negotiation on every offer</li><!-- /wp:list-item -->\n	<!-- wp:list-item --><li>Guidance through inspections, appraisal, and closing</li><!-- /wp:list-item -->\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--40)\">\n	<!-- wp:button -->\n	<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/contact/\">Get a Listing Plan</a></div>\n	<!-- /wp:button -->\n\n	<!-- wp:button {\"className\":\"tb-button-outline\",\"te